#include <fstream>
#include <iomanip>
namespace regrip_film_native {
class FilmSphereCoupledCorrection final:public sofa::core::objectmodel::BaseObject {
public:
 using State=sofa::core::behavior::MechanicalState<sofa::defaulttype::Vec3Types>;
 using Solver=sofa::component::constraint::lagrangian::solver::GenericConstraintSolver;
 using BaseLink=sofa::core::objectmodel::BaseLink;
 SOFA_CLASS(FilmSphereCoupledCorrection,sofa::core::objectmodel::BaseObject);
 sofa::core::objectmodel::SingleLink<FilmSphereCoupledCorrection,State,BaseLink::FLAG_STOREPATH|BaseLink::FLAG_STRONGLINK>root,body,sphere;
 sofa::core::objectmodel::SingleLink<FilmSphereCoupledCorrection,Solver,BaseLink::FLAG_STOREPATH|BaseLink::FLAG_STRONGLINK>solver;
 sofa::core::objectmodel::SingleLink<FilmSphereCoupledCorrection,sofa::core::objectmodel::BaseObject,BaseLink::FLAG_STOREPATH|BaseLink::FLAG_STRONGLINK>field;
 sofa::core::objectmodel::Data<std::string>filename;
 sofa::core::objectmodel::Data<double>radius,contactDistance,rayleighMass;
 std::vector<Point>previous,previousV,beginWorld;State::Coord centerBegin;double last=-1;std::ofstream journal,trace;
 FilmSphereCoupledCorrection():root(initLink("root","Independent root displacement DOFs")),body(initLink("body","Actual world geometry")),sphere(initLink("sphere","Fixed Vec3 sphere center")),solver(initLink("solver","Native constraint impulse data")),field(initLink("field","Existing FilmRailTendon ForceField;public Data read only")),filename(initData(&filename,std::string(),"filename","Exclusive coupled Newton journal")),radius(initData(&radius,8.,"radius","Fixed sphere radius")),contactDistance(initData(&contactDistance,.01,"contactDistance","MUST equal native contactDistance")),rayleighMass(initData(&rayleighMass,2.,"rayleighMass","MUST equal BE mass damping")){f_listening.setValue(true);}
 template<class T>T parameter(const char*name,T fallback,bool optional=false)const{auto*data=field->findData(name);if(!data&&optional)return fallback;auto*typed=dynamic_cast<sofa::core::objectmodel::Data<T>*>(data);if(!typed)throw std::runtime_error(std::string("Missing/incorrect film parameter:")+name);return typed->getValue();}
 State*localState()const{auto*state=dynamic_cast<State*>(field->getContext()->getMechanicalState());if(!state)throw std::runtime_error("coupled film displacement state missing");return state;}
 static std::vector<Point>points(const State::VecCoord&x){std::vector<Point>p(x.size());for(unsigned i=0;i<x.size();++i)for(unsigned d=0;d<3;++d)p[i][d]=x[i][d];return p;}
 void init()override{BaseObject::init();if(!root||!body||!sphere||!solver||!field||field->getClassName()!="FilmRailTendon")throw std::runtime_error("coupled correction links/model");std::ifstream old(filename.getValue());if(filename.getValue().empty()||old)throw std::runtime_error("coupled journal exists/empty");journal.open(filename.getValue());trace.open(filename.getValue()+".newton.log");trace<<std::setprecision(17)<<std::unitbuf;journal<<std::setprecision(17)<<"time,active_row,lambda_native,lambda_coupled,iterations,absolute_impulse_residual,gap_mm,status\n";}
 void handleEvent(sofa::core::objectmodel::Event*event)override{
  if(dynamic_cast<sofa::simulation::AnimateBeginEvent*>(event)){previous=points(localState()->read(sofa::core::vec_id::read_access::position)->getValue());previousV=points(localState()->read(sofa::core::vec_id::read_access::velocity)->getValue());beginWorld=points(body->read(sofa::core::vec_id::read_access::position)->getValue());centerBegin=sphere->read(sofa::core::vec_id::read_access::position)->getValue().at(0);return;}
  if(!dynamic_cast<sofa::simulation::AnimateEndEvent*>(event))return;double time=getContext()->getTime();if(time==last)return;last=time;auto lambda=solver->d_constraintForces.getValue();unsigned active=0,activeRow=0;for(unsigned i=0;i<lambda.size();++i)if(lambda[i]>0){++active;activeRow=i;}if(!active){journal<<time<<",null,null,null,0,null,null,no_active_contact\n";journal.flush();return;}for(double value:lambda)if(!std::isfinite(value))throw std::runtime_error("nonfinite native multiplier");if(active!=1)throw std::runtime_error("coupled single-plane model:multiple active rows require general active set");
  auto center=sphere->read(sofa::core::vec_id::read_access::position)->getValue().at(0);for(unsigned d=0;d<3;++d)if(center[d]!=centerBegin[d])throw std::runtime_error("moving sphere is outside single-plane qualification");
  Assembly model(parameter<unsigned>("nx",0));model.guideIntervals=parameter<unsigned>("guideIntervals",4,true);model.guideOffset=parameter<double>("guideOffset",0);model.bondK=parameter<double>("bondStiffness",0);model.rootGuideSecondOrder=parameter<bool>("rootGuideSecondOrder",false,true);double maximum=parameter<double>("maximumTension",0),ramp=parameter<double>("rampTime",0),release=parameter<double>("releaseBegin",0),end=parameter<double>("releaseEnd",0);double tension=maximum*std::clamp(time/ramp,0.,1.)*(time<=release?1.:std::clamp((end-time)/(end-release),0.,1.));
  struct Plane{unsigned row;std::vector<Point>J;double target;};std::vector<Plane>planes;const auto&jac=body->read(sofa::core::vec_id::read_access::constraintJacobian)->getValue();for(auto row=jac.begin();row!=jac.end();++row){Point normal{},weighted{};double sum=0;std::vector<Point>J(model.size());for(auto col=row.begin();col!=row.end();++col){Point value{col.val()[0],col.val()[1],col.val()[2]};J.at(col.index())=value;normal=add(normal,value);double w=col.val().norm();weighted=add(weighted,scale(beginWorld.at(col.index()),w));sum+=w;}if(sum==0)continue;weighted=scale(weighted,1/sum);Point radial=sub(weighted,{center[0],center[1],center[2]});if(!(dot(radial,radial)>0))throw std::runtime_error("degenerate sphere event normal");if(std::abs(dot(normal,normal)-1)>1e-10||dot(normal,radial)/std::sqrt(dot(radial,radial))<1-1e-10)throw std::runtime_error("non-normal/friction/degenerate contact row unsupported");planes.push_back({static_cast<unsigned>(row.index()),J,normal[0]*center[0]+normal[1]*center[1]+normal[2]*center[2]+radius.getValue()+contactDistance.getValue()});}
  auto selected=std::find_if(planes.begin(),planes.end(),[&](const auto&p){return p.row==activeRow;});if(selected==planes.end())throw std::runtime_error("active native contact row missing");auto*mass=field->getContext()->getMass();if(!mass)throw std::runtime_error("actual assembly mass missing");std::vector<double>masses(model.size());for(unsigned i=0;i<model.size();++i){masses[i]=mass->getElementMass(i);if(!std::isfinite(masses[i])||masses[i]<=0)throw std::runtime_error("nonpositive assembly mass");}
  double oldLambda=lambda[activeRow],h=getContext()->getDt();CoupledPlaneStep step(model,masses,h,rayleighMass.getValue(),tension,previous,previousV,selected->J,selected->target);trace<<"BEGIN_STEP "<<time<<'\n';auto result=step.solve(points(localState()->read(sofa::core::vec_id::read_access::velocity)->getValue()),oldLambda,&trace);auto rest=model.rest();for(const auto&p:planes){double gap=-p.target;for(unsigned i=0;i<model.size();++i)gap+=dot(p.J[i],add(rest[i],result.displacement[i]));if(gap< -1e-10)throw std::runtime_error("inactive contact becomes active;requires general active set;state NOT published");}
  auto x=root->read(sofa::core::vec_id::read_access::position)->getValue();auto v=root->read(sofa::core::vec_id::read_access::velocity)->getValue();for(unsigned i=0;i<model.size();++i)for(unsigned d=0;d<3;++d)if(step.index[3*i+d]>=0&&step.weight[3*i+d]==1){x[i][d]=result.displacement[i][d];v[i][d]=result.velocity[i][d];}root->write(sofa::core::vec_id::write_access::position)->setValue(x);root->write(sofa::core::vec_id::write_access::velocity)->setValue(v);sofa::simulation::common::MechanicalOperations mop(sofa::core::ExecParams::defaultInstance(),getContext());mop.propagateXAndV(sofa::core::vec_id::write_access::position,sofa::core::vec_id::write_access::velocity);lambda[activeRow]=result.lambda;solver->d_constraintForces.setValue(lambda);journal<<time<<','<<activeRow<<','<<oldLambda<<','<<result.lambda<<','<<result.iterations<<','<<result.residual<<','<<result.gap<<",solved\n";journal.flush();
 }
};
void registerFilmSphereCoupledCorrection(sofa::core::ObjectFactory*f){f->registerObjects(sofa::core::ObjectRegistrationData("Experimental single-active-plane monolithic BE correction;fixed frictionless sphere only;unsupported events rejected").add<FilmSphereCoupledCorrection>());}
}
